using System.Net;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;
using WireMock.RequestBuilders;
using WireMock.ResponseBuilders;
using WireMock.Server;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>
/// Contract-level coverage of HttpPaymentGateway against a mocked provider: proves the outbound
/// request shape and the inbound decision mapping, including the provider's outright refusal (402).
/// </summary>
public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly WireMockServer server = WireMockServer.Start();

    private HttpPaymentGateway CreateSut()
    {
        var client = new HttpClient { BaseAddress = new Uri(server.Url!) };
        return new HttpPaymentGateway(client);
    }

    [Fact]
    public async Task Sends_the_reference_amount_and_currency_the_provider_expects()
    {
        server
            .Given(Request.Create()
                .WithPath("/v1/authorizations")
                .UsingPost()
                .WithBody(b => b != null
                    && b.Contains("\"reference\":\"ORD-1\"")
                    && b.Contains("\"amount\":42.5")
                    && b.Contains("\"currency\":\"EUR\"")))
            .RespondWith(Response.Create()
                .WithStatusCode(HttpStatusCode.OK)
                .WithHeader("Content-Type", "application/json")
                .WithBody("""{"status":"approved"}"""));

        var sut = CreateSut();

        var outcome = await sut.AuthorizeAsync("ORD-1", new Money(42.50m, "eur"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task An_approved_status_in_the_body_is_read_back_as_approved()
    {
        server
            .Given(Request.Create().WithPath("/v1/authorizations").UsingPost())
            .RespondWith(Response.Create()
                .WithStatusCode(HttpStatusCode.OK)
                .WithHeader("Content-Type", "application/json")
                .WithBody("""{"status":"approved"}"""));

        var sut = CreateSut();

        var outcome = await sut.AuthorizeAsync("ORD-2", new Money(10m, "USD"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_status_in_the_body_is_read_back_as_declined()
    {
        server
            .Given(Request.Create().WithPath("/v1/authorizations").UsingPost())
            .RespondWith(Response.Create()
                .WithStatusCode(HttpStatusCode.OK)
                .WithHeader("Content-Type", "application/json")
                .WithBody("""{"status":"declined"}"""));

        var sut = CreateSut();

        var outcome = await sut.AuthorizeAsync("ORD-3", new Money(10m, "USD"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task The_provider_refusing_the_request_outright_with_402_is_read_back_as_declined()
    {
        server
            .Given(Request.Create().WithPath("/v1/authorizations").UsingPost())
            .RespondWith(Response.Create().WithStatusCode(HttpStatusCode.PaymentRequired));

        var sut = CreateSut();

        var outcome = await sut.AuthorizeAsync("ORD-4", new Money(10m, "USD"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unrecognized_status_value_is_treated_as_declined()
    {
        server
            .Given(Request.Create().WithPath("/v1/authorizations").UsingPost())
            .RespondWith(Response.Create()
                .WithStatusCode(HttpStatusCode.OK)
                .WithHeader("Content-Type", "application/json")
                .WithBody("""{"status":"pending_review"}"""));

        var sut = CreateSut();

        var outcome = await sut.AuthorizeAsync("ORD-5", new Money(10m, "USD"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unexpected_server_error_surfaces_as_a_failure_instead_of_a_silent_decline()
    {
        server
            .Given(Request.Create().WithPath("/v1/authorizations").UsingPost())
            .RespondWith(Response.Create().WithStatusCode(HttpStatusCode.InternalServerError));

        var sut = CreateSut();

        await Assert.ThrowsAsync<HttpRequestException>(
            () => sut.AuthorizeAsync("ORD-6", new Money(10m, "USD"), CancellationToken.None));
    }

    public void Dispose() => server.Dispose();
}

